From a6098b4b7b8af5712ac65e2f86ab16f4200c05a4 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:34:12 +0100
Subject: [PATCH] applets/digital-clock: say tomorrow or yesterday for other
 time zones

Times in other time zones that fall on a different day were followed by
the weekday name, which makes you work out how it relates to today. Show
"tomorrow" or "yesterday" instead, keeping the weekday for larger gaps.

BUG: 518383
---
 applets/digital-clock/main.qml | 10 +++++++++-
 1 file changed, 9 insertions(+), 1 deletion(-)

diff --git a/applets/digital-clock/main.qml b/applets/digital-clock/main.qml
index 5b983ef25b..405196775c 100644
--- a/applets/digital-clock/main.qml
+++ b/applets/digital-clock/main.qml
@@ -60,7 +60,15 @@ PlasmoidItem {
             formattedTime = Qt.locale().toString(dateTime, compactRepresentationItem.item.timeFormat);
         }

-        if (dateTime.getDay() !== currentClock.dateTime.getDay()) {
+        const current = currentClock.dateTime;
+        const dayDifference = Math.round((Date.UTC(dateTime.getFullYear(), dateTime.getMonth(), dateTime.getDate())
+            - Date.UTC(current.getFullYear(), current.getMonth(), current.getDate())) / (1000 * 60 * 60 * 24));
+
+        if (dayDifference === 1) {
+            return i18nc("@info time in another time zone, where it is already the next day", "%1 tomorrow", formattedTime);
+        } else if (dayDifference === -1) {
+            return i18nc("@info time in another time zone, where it is still the previous day", "%1 yesterday", formattedTime);
+        } else if (dayDifference !== 0) {
             formattedTime += " " + Qt.locale().toString(dateTime, "dddd");
         }

